        experiments.append({"terms": linear_terms, "window": 9, "weak_window": 0, "validation": checked, "training_rmse": fitted["training_rmse"]})
        if checked["stable"] and value > best_value:
            best_value = value
            best = {"terms": linear_terms, "window": 9, "weak_window": 0, "threshold": 0.04}
    except Exception as error:
