                try:
                    fitted = tools.fit_model(observations[:-1], problem["dt"], terms, window=window, degree=3, ridge=1e-6, threshold=threshold, weak_window=weak_window)
                    checked = tools.validate(fitted["model"], observations[-1:], problem["dt"], fraction=0.15)
