    triggers = meta_research_trigger(context)
    # Only enter probe branch if there are actual current failures or evidence of degradation
    if triggers and any(t.get('kind') in ['current_parent_failure', 'two_public_non_improving_offspring'] for t in triggers):
        return meta_research_cycle(context, broker, triggers)
    # Otherwise, perform ordinary task improvement
    return research_cycle(context, broker)

def select_parent(archive):
    if not archive:
        return None
    # Use quality-per-cost metric instead of static heuristic
    best = archive[0]
    best_priority = (best.get('score') or 0.0) / (best.get('work_units') or 1) if best.get('work_units') else 0.0
    for node in archive[1:]:
        priority = (node.get('score') or 0.0) / (node.get('work_units') or 1) if node.get('work_units') else 0.0
