def make_library(dimension, nonlinear, extended):
    terms = ["1"]
    variables = ["x" + str(i) for i in range(dimension)]
    terms = terms + variables
    if nonlinear:
        for i in range(dimension):
            for j in range(i, dimension):
                terms.append(variables[i] + "*" + variables[j])
                for k in range(j, dimension):
                    terms.append(variables[i] + "*" + variables[j] + "*" + variables[k])
    if extended:
        for variable in variables:
            terms.append("sin(" + variable + ")")
            terms.append("tanh(" + variable + ")")
            terms.append(variable + "/(1+" + variable + "**2)")
    return terms

def adaptive_fit(observations, dt, terms, window, weak_window, threshold, tools):
    """
    Attempt fit with provided parameters. If it fails or budget is high, 
    try fallback strategies before giving up.
    """
    try:
        fitted = tools.fit_model(observations, dt, terms, window=window, degree=3, ridge=0.000001, threshold=threshold, weak_window=weak_window)
        return fitted, None
    except Exception as error:
        # If first attempt fails, try weaker parameters to get any model back
        if weak_window > 0:
            try:
                fitted = tools.fit_model(observations, dt, terms, window=9, degree=3, ridge=1e-4, threshold=threshold*1.5, weak_window=0)
                return fitted, None
            except:
                pass
        # If extended terms caused issues, try without them
        if len(terms) > 10:
            simple_terms = ["1"] + [t for t in terms if "sin" not in t and "tanh" not in t and "/(" not in t]
            if len(simple_terms) < len(terms):
                try:
                    fitted = tools.fit_model(observations, dt, simple_terms, window=window, degree=3, ridge=1e-5, threshold=threshold, weak_window=weak_window)
                    return fitted, None
                except:
                    pass
        return None, error

def solve(problem, tools):
    observations = problem["observations"]
    n_traj = len(observations)

    # Smart split: use multiple trajectories for validation if available
    if n_traj >= 3:
        n_train = max(1, n_traj - 2)
        training = observations[:n_train]
        validation = observations[n_train:n_train+1]
    else:
        training = observations[:-1]
        validation = observations[-1:]

    experiments = []
    best = None
    best_score = -float("inf")

    # Prioritized search: start with most likely successful configurations
    search_configs = [
        # (nonlinear, extended, window, weak_window, threshold)
        (True, False, 9, 0, 0.03),      # Polynomial with derivatives
        (True, False, 13, 7, 0.04),     # Polynomial with weak formulation
        (False, False, 9, 0, 0.02),     # Linear only - robust fallback
        (True, True, 9, 0, 0.05),       # Extended library
        (True, True, 13, 7, 0.06),      # Extended with weak
    ]

    best_terms = None
    best_config = None

    for nonlinear, extended, window, weak_window, threshold in search_configs:
        terms = make_library(problem["dimension"], nonlinear, extended)

        fitted, error = adaptive_fit(training, problem["dt"], terms, window, weak_window, threshold, tools)

        if error:
            experiments.append({"terms": terms[:5], "window": window, "weak_window": weak_window, "error": str(error)[:100]})
            continue

        try:
            checked = tools.validate(fitted["model"], validation, problem["dt"], fraction=0.2)
            # Score with complexity penalty
            value = checked["score"] - 0.001 * checked["complexity"]

            experiments.append({
                "terms": terms[:5],
                "window": window,
                "weak_window": weak_window,
                "training_rmse": fitted["training_rmse"],
                "val_score": checked["score"],
                "complexity": checked["complexity"]
            })

            if checked["stable"] and value > best_score:
                best_score = value
                best_terms = terms
                best_config = {
                    "window": window,
                    "weak_window": weak_window,
                    "threshold": threshold,
                    "model": fitted["model"]
                }
        except Exception as e:
            experiments.append({"terms": terms[:5], "window": window, "error": str(e)[:100]})

    # If no validation succeeded, try simplest possible model on all data
    if best_config is None:
        simple_terms = ["1", "x0"]
        if problem["dimension"] > 1:
            simple_terms.append("x1")

        try:
            fitted = tools.fit_model(observations, problem["dt"], simple_terms, window=9, degree=3, ridge=0.001, threshold=0.1, weak_window=0)
            best_config = {
                "window": 9,
                "weak_window": 0,
                "threshold": 0.1,
                "model": fitted["model"]
            }
            best_terms = simple_terms
            experiments.append({"fallback": True, "terms": simple_terms})
        except:
            # Absolute minimum: return zero model
            zero_coeffs = [[0.0] * 1 for _ in range(problem["dimension"])]
            return {
                "model": {
                    "terms": ["1"],
                    "coefficients": zero_coeffs
                },
                "hypotheses": [],
                "experiments": experiments,
                "limitations": ["No model could be fitted; returning zero"]
            }

    # Refit on full data if we have enough budget
    if tools.receipts().get("cumulative_work_units", 0) < 0.8 * problem.get("numerical_budget", 20000000):
        try:
            final = tools.fit_model(
                observations, problem["dt"], best_terms,
                window=best_config["window"], degree=3, ridge=0.000001,
                threshold=best_config["threshold"],
                weak_window=best_config["weak_window"]
            )
            best_config["model"] = final["model"]
        except:
            pass  # Keep the already-fitted model

    return {
        "model": best_config["model"],
        "hypotheses": [
            {"claim": "Sparse expression regression identifies governing equations",
             "falsifier": "Systematic failure on held-out trajectories"}
        ],
        "experiments": experiments,
        "limitations": [
            "Adaptive fallback may select oversimplified models",
            "Weak formulation is integral collocation primitive, not full WSINDy",
            "Synthetic recovery demonstration, not new natural law"
        ]
    }

