import math

def improve(context, broker):
    """Default to task improvement unless low-cost evidence justifies meta-research."""
    triggers = meta_research_trigger(context)
    if not triggers:
        return research_cycle(context, broker)

    # Gate expensive meta-research on clear, low-cost evidence
    if len(triggers) < 2 and not any(t.get("kind") == "current_parent_failure" for t in triggers):
        return research_cycle(context, broker)

    # Proceed with meta-research for stronger evidence
    return meta_research_cycle(context, broker, triggers)

def select_parent(archive):
    if not archive:
        return None
    best = archive[0]
    best_priority = (best.get("score") or 0.0) + 2.0 / (1 + best.get("children", 0))
    for node in archive[1:]:
        priority = (node.get("score") or 0.0) + 2.0 / (1 + node.get("children", 0))
        if priority > best_priority:
            best = node
            best_priority = priority
    return best.get("id")

source_components_by_sha256.60060ff03e6edd2118c5583d4456f52ae2ba1711:
def bbh_atom(tokens, index):
    token = tokens[index]
    if token == "not":
        value, index = bbh_atom(tokens, index + 1)
        return not value, index
    if token == "(":
        value, index = bbh_or(tokens, index + 1)
        if tokens[index] != ")":
            raise ValueError("Expected a closing parenthesis")
        return value, index + 1
    if token not in ["True", "False"]:
        raise ValueError("Unknown Boolean token")
    return token == "True", index + 1

def bbh_and(tokens, index):
    value, index = bbh_atom(tokens, index)
    while index < len(tokens) and tokens[index] == "and":
        right, index = bbh_atom(tokens, index + 1)
        value = value and right
    return value, index

def bbh_or(tokens, index):
    value, index = bbh_and(tokens, index)
    while index < len(tokens) and tokens[index] == "or":
        right, index = bbh_and(tokens, index + 1)
        value = value or right
    return value, index

def solve(problem, tools):
    prompt = problem["input"]
    if problem["category"] == "word_sorting":
        if "List:" not in prompt:
            raise ValueError("Word sorting needs the public List: input")
        words = prompt.split("List:", 1)[1].split()
        return {"answer": " ".join(sorted(words))}
    if problem["category"] == "boolean_expressions":
        tokens = prompt.replace("(", " ( ").replace(")", " ) ").split()
        if tokens and tokens[-1] == "is":
            tokens = tokens[:-1]
        value, index = bbh_or(tokens, 0)
        if index != len(tokens):
            raise ValueError("Unexpected remaining Boolean tokens")
        return {"answer": "True" if value else "False"}
    raise ValueError("Unsupported task category")

