def make_library(dimension, nonlinear, extended):
    terms = ["1"]
    variables = ["x" + str(i) for i in range(dimension)]
    terms = terms + variables
    if nonlinear:
        for i in range(dimension):
            for j in range(i, dimension):
                terms.append(variables[i] + "*" + variables[j])
                for k in range(j, dimension):
                    terms.append(variables[i] + "*" + variables[j] + "*" + variables[k])
    if extended:
        for variable in variables:
            terms.append("sin(" + variable + ")")
            terms.append("tanh(" + variable + ")")
            terms.append(variable + "/(1+" + variable + "**2)")
    return terms

def solve(problem, tools):
    observations = problem["observations"]
    training = observations[:-1]
    validation = observations[-1:]
    experiments = []
    best = None
    best_value = -1000000

    # Budget tracking
    work_at_start = tools.work_units
    batch_limit = problem.get("numerical_budget", {}).get("batch_limit", 20000000)
    remaining_tasks = problem.get("numerical_budget", {}).get("remaining_tasks", 1)
    recommended_limit = problem.get("numerical_budget", {}).get("recommended_limit", 20000000)
    # Adaptive work budget: 90% of recommended limit, scaled by remaining tasks
    work_budget = min(recommended_limit, 0.9 * batch_limit / max(remaining_tasks, 1))

    # Mechanism: Prioritize weak/integral collocation for noise robustness and cross-initial-condition generalization.
    # This addresses the diagnosed failure: strong derivative-based fits fail on noisy observations and different initial conditions.
    # Order: weak-first, then strong, then extended. This favors stable formulations early, improving generalization.
    library_configs = [
        (False, False, "weak_first"),  # Weak/linear (robust)
        (True, False, "strong_first"), # Strong/nonlinear
        (True, True, "extended_first") # Extended with transcendental functions
    ]
    param_configs = [
        (9, 2, 0.04), (13, 2, 0.06), (9, 0, 0.04), (13, 0, 0.06)
    ]

    for nonlinear, extended, strategy in library_configs:
        terms = make_library(problem["dimension"], nonlinear, extended)
        for window, weak_window, threshold in param_configs:
            # Check work budget before each fit attempt
            current_work = tools.work_units
            if current_work - work_at_start > work_budget:
                break
            try:
                # Mechanism: Apply integral collocation only during weak_first strategy for noise robustness.
                actual_weak_window = weak_window if strategy == "weak_first" else 0
                fitted = tools.fit_model(training, problem["dt"], terms, window=window, degree=3, ridge=0.000001, threshold=threshold, weak_window=actual_weak_window)
                checked = tools.validate(fitted["model"], validation, problem["dt"], fraction=0.15)
                value = checked["score"] - 0.0008 * checked["complexity"]
                experiments.append({"terms": terms, "window": window, "weak_window": actual_weak_window, "validation": checked, "training_rmse": fitted["training_rmse"], "strategy": strategy})
                if checked["stable"] and value > best_value:
                    best_value = value
                    best = {"terms": terms, "window": window, "weak_window": actual_weak_window, "threshold": threshold, "strategy": strategy}
            except Exception as error:
                experiments.append({"terms": terms, "window": window, "error": str(error), "strategy": strategy})
        if tools.work_units - work_at_start > work_budget:
            break

    if best is None:
        raise ValueError("No numerically valid observation-validated model")
    final = tools.fit_model(observations, problem["dt"], best["terms"], window=best["window"], degree=3, ridge=0.000001, threshold=best["threshold"], weak_window=best["weak_window"])
    return {"model": final["model"], "hypotheses": [{"claim": "Weak/integral collocation reduces noise sensitivity and improves cross-initial-condition generalization", "falsifier": "Failure on independent initial conditions or longer horizons"}], "experiments": experiments, "limitations": ["Selected on one withheld noisy observation trajectory then refitted", "This integral-collocation portfolio is not a full WSINDy reproduction", "Prediction support alone does not establish unique mechanisms or a new natural law", "Work-budget adaptive stopping may sacrifice completeness for budget preservation", "Strategy-based ordering is heuristic; no proven optimality"]}

