def validate_stability(model, initial_state, dt, problem_dimension, max_steps=500):
    """Quick stability diagnostic: integrate a short trajectory and check for divergence."""
    try:
        trajectory = tools.integrate(model, initial_state, dt, max_steps, substeps=4)
        # Check for divergence: if any state magnitude exceeds 1e6, it's unstable
        for state in trajectory:
            if any(abs(val) > 1e6 for val in state):
                return False
        return True
    except Exception:
        return False

def adaptive_threshold_selection(training_rmse, dt, window):
    """Select threshold based on estimated noise level from training fit."""
    # Heuristic: higher noise -> higher threshold to avoid fitting noise
    noise_estimate = training_rmse / (window * dt)
    if noise_estimate < 0.01:
        return 0.03
    elif noise_estimate < 0.1:
        return 0.06
    else:
        return 0.1

def solve(problem, tools):
    observations = problem["observations"]
    training = observations[:-1]
    validation = observations[-1:]
    experiments = []
    best = None
    best_value = -1000000

    # Extended parameter grid with adaptive threshold selection
    for nonlinear, extended in [(False, False), (True, False), (True, True)]:
        terms = make_library(problem["dimension"], nonlinear, extended)
        # Expanded window/weak_window grid
        for window, weak_window in [(7, 0), (9, 0), (9, 3), (11, 5), (13, 0), (13, 7), (15, 10)]:
            try:
                # Initial fit to get training_rmse for adaptive threshold
                initial_fit = tools.fit_model(training, problem["dt"], terms, window=window, degree=3, ridge=0.000001, threshold=0.05, weak_window=weak_window)
                adaptive_thresh = adaptive_threshold_selection(initial_fit["training_rmse"], problem["dt"], window)

                # Main fit with adaptive threshold
                fitted = tools.fit_model(training, problem["dt"], terms, window=window, degree=3, ridge=0.000001, threshold=adaptive_thresh, weak_window=weak_window)
                checked = tools.validate(fitted["model"], validation, problem["dt"], fraction=0.15)
                value = checked["score"] - 0.0008 * checked["complexity"]

                # Stability pre-check before accepting model
                if checked["stable"]:
                    # Test stability on a different initial condition (first state from validation)
                    initial_state = validation[0][0] if validation[0] else [0.0] * problem["dimension"]
                    is_stable = validate_stability(fitted["model"], initial_state, problem["dt"], problem["dimension"])

                    experiments.append({"terms": terms, "window": window, "weak_window": weak_window, 
                                       "validation": checked, "training_rmse": fitted["training_rmse"],
                                       "stability_test": is_stable})

                    if is_stable and value > best_value:
                        best_value = value
                        best = {"terms": terms, "window": window, "weak_window": weak_window, 
                               "threshold": adaptive_thresh, "model": fitted["model"]}
                else:
                    experiments.append({"terms": terms, "window": window, "weak_window": weak_window,
                                       "validation": checked, "stable": False})
            except Exception as error:
                experiments.append({"terms": terms, "window": window, "error": str(error)})

    if best is None:
        # Fallback: try simplest model without stability check
        terms = make_library(problem["dimension"], False, False)
        try:
            fitted = tools.fit_model(observations, problem["dt"], terms, window=9, degree=3, ridge=0.000001, threshold=0.05)
            return {"model": fitted["model"], 
