                                 "falsifier": "High NRMSE on held-out data"}],
                   "experiments": experiments, 
                   "limitations": ["No stable model found in extended search", 
                                  "Fallback model may oversimplify dynamics"]}
        except:
            raise ValueError("No numerically valid observation-validated model")

    # Final refit on all observations with best parameters
    final = tools.fit_model(observations, problem["dt"], best["terms"], window=best["window"], 
                           degree=3, ridge=0.000001, threshold=best["threshold"], weak_window=best["weak_window"])
    return {"model": final["model"], 
           "hypotheses": [{"claim": "Sparse expressions explain the observed state derivatives", 
                         "falsifier": "Failure on independent initial conditions or longer horizons"}], 
           "experiments": experiments, 
           "limitations": ["Selected on one withheld noisy observation trajectory then refitted", 
                          "Stability diagnostic uses short integration (500 steps)", 
